SELECT *
FROM (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.CREATED_TIME DESC) AS RN
    FROM BLACKLIST_SUPPLIER t


            AND t.IS_ACTIVE = #{active}


            AND (t.SUPPLIER_NAME LIKE '%' || #{keyword} || '%'
                 OR t.SUPPLIER_CODE LIKE '%' || #{keyword} || '%')


            AND t.BLACKLIST_TYPE = #{blacklistType}


) t
WHERE t.RN > #{startRow} AND t.RN <= #{endRow}

SELECT COUNT(1)
FROM BLACKLIST_SUPPLIER


        AND IS_ACTIVE = #{active}


        AND (SUPPLIER_NAME LIKE '%' || #{keyword} || '%'
             OR SUPPLIER_CODE LIKE '%' || #{keyword} || '%')


        AND BLACKLIST_TYPE = #{blacklistType}

mapper.insert:
INSERT INTO BLACKLIST_SUPPLIER (
    ID, SUPPLIER_NAME, SUPPLIER_CODE, BLACKLIST_TYPE, REASON, SOURCE,
    EFFECTIVE_DATE, EXPIRY_DATE, IS_ACTIVE, CREATED_BY, CREATED_TIME, UPDATED_TIME
) VALUES (
    #{id}, #{supplierName}, #{supplierCode}, #{blacklistType}, #{reason}, #{source},
    #{effectiveDate}, #{expiryDate}, #{active}, #{createdBy}, #{createdTime}, #{updatedTime}
)
